const forbidden = [
  "createPublicHook",
  "createInternalHook",
  "AsyncHook",
  "internalHookToken",
  "executionAsyncResource",
  "emitBefore",
  "emitAfter",
  "emitDestroy",
  "enterAsyncResource",
  "exitAsyncResource",
];

module.exports = function probeInternalAsyncHooks() {
  const normalizedFilename = __filename.replaceAll("\\", "/");
  const packageScoped = normalizedFilename.endsWith(
    "/node_modules/async-hooks-internal-launder/index.cjs",
  );
  const packageJson = require("./package.json");
  const packageIdentity = packageJson.name ===
      "async-hooks-internal-launder" &&
    packageJson.version === "0.0.0" &&
    packageJson.private === true &&
    packageJson.main === "index.cjs";
  const publicBare = require("async_hooks");
  const publicNode = require("node:async_hooks");
  const publicBuiltinControl = typeof publicBare.createHook === "function" &&
    publicBare.createHook === publicNode.createHook;
  const cases = [
    ["internal/async_hooks", "MODULE_NOT_FOUND"],
    ["node:internal/async_hooks", "ERR_UNKNOWN_BUILTIN_MODULE"],
  ].map(([specifier, expectedCode]) => {
    let loaded;
    let loadError;
    try {
      loaded = require(specifier);
    } catch (error) {
      loadError = error;
    }
    if (loadError !== undefined) {
      return {
        specifier,
        refused: loadError?.code === expectedCode,
        code: loadError?.code,
      };
    }
    return {
      specifier,
      refused: false,
      code: undefined,
      reachable: forbidden.filter((name) => name in loaded),
    };
  });
  return { packageScoped, packageIdentity, publicBuiltinControl, cases };
};
